import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`google-ads`,heroTitle:`Build your Google Ads strategy in minutes`,heroSubtitle:`Perplexity Computer researches your market, finds the keywords worth bidding on, and builds your entire ad strategy automatically.`,inputUrlCta:`Build my strategy`,inputUrlPrefill:`Go to {url} and build a complete Google Ads strategy. Analyze the business, value proposition, target audience, and top competitors. Research high-intent keywords across branded, non-branded, competitor, and long-tail categories — include search volume, average CPC, competition level, and estimated conversion potential for each. Group keywords into tightly themed ad groups with single keyword ad group (SKAG) structure where appropriate. Write 3+ responsive search ad variations per ad group with unique headlines, descriptions, and sitelink extensions. Build a negative keyword list to eliminate wasted spend. Estimate monthly budget, projected impressions, clicks, CTR, and cost per acquisition at different spend levels. Deliver everything in a Google Sheets-ready format with keyword lists, ad copy, bid recommendations, negative keywords, and a 90-day budget ramp plan.`,heroOverlaySteps:[`Researching your market, competitors, and target audience`,`Finding high-intent keywords with volume and CPC data`,`Building ad groups, writing copy, and setting bid targets`,`Full campaign plan with budget forecast, ready to launch`],generatingSteps:[`Visiting {url} to understand your product, audience, and competitors`,`Designing an agent to research keywords, search volume, and CPC data`,`Configuring ad group structure, copy variations, and bid recommendations`,`Setting up campaign plan with budget forecast and performance projections`],featureSectionTitle:`From URL to ad campaign`,featureCardTitles:[`Connects to your tools`,`Campaign ready to launch`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Slack — Computer delivers your keyword lists, ad copy, and budget plans straight into the tools you already use.`,`Keyword lists. Ad copy. Bid targets. Budget forecasts. Computer delivers a complete Google Ads strategy your team can execute immediately.`],capabilitySectionTitle:`Your paid search team, on demand`,capabilitySectionSubtitle:`Enter your URL, get back a complete Google Ads strategy.`,capabilityCards:[{title:`Keyword Research`,description:`Computer finds high-intent keywords with search volume, CPC, and competition data — filtered for what actually converts.`},{title:`Ad Group Structure`,description:`Computer groups keywords into tightly themed ad groups — so your quality scores stay high and your CPCs stay low.`},{title:`Ad Copy & Extensions`,description:`Computer writes multiple ad copy variations for each ad group — headlines, descriptions, and sitelinks ready to upload.`},{title:`Budget & Bid Strategy`,description:`Computer estimates monthly spend, projected clicks, and cost per acquisition — so you know what to expect before you launch.`},{title:`Knows Your Market`,description:`Computer remembers your business, competitors, and past campaigns — so every strategy builds on what it already knows.`},{title:`Monthly Refresh`,description:`Computer updates your keyword lists and bid recommendations every month — adding new opportunities and cutting wasted spend.`}]});export{t as default};
